@app.get("/orders/{oid}")
def get_order(oid: int, user=Depends(current_user)):
    # Ownership in the query means an unauthorized object simply does not exist
    order = db.query(Order).filter(
        Order.id == oid,
        Order.owner_id == user.id
    ).first()
    if not order:
        raise HTTPException(404)   # no not-found vs forbidden distinction, avoiding enumeration
    return order

