code.good:
type UpdateProfile = { displayName?: string; avatarUrl?: string };

app.patch("/users/:id", async (req, res) => {
  const body = req.body as UpdateProfile;   // an allowlist at the type level
  const patch: Record<string, unknown> = {};
  if (typeof body.displayName === "string") patch.display_name = body.displayName;
  if (typeof body.avatarUrl === "string")   patch.avatar_url  = body.avatarUrl;
  // role, balance and friends are not in the allowlist and cannot be written
  await User.update(req.params.id, patch);
  res.json({ id: req.params.id, displayName: body.displayName });
});

